import 'dart:math';

import 'package:flutter/foundation.dart';

/// A new-episode alert generated by the app itself (no external push service).
@immutable
class AppNotification {
  const AppNotification({
    required this.animeId,
    required this.animeTitle,
    required this.episodeId,
    required this.episodeNumber,
    required this.createdAt,
    this.posterUrl,
    this.read = false,
  });

  final String animeId;
  final String animeTitle;
  final String episodeId;
  final int episodeNumber;
  final String? posterUrl;
  final DateTime createdAt;
  final bool read;

  /// Stable identity so the same episode is never announced twice.
  String get id => '$animeId::$episodeId';

  /// Notification tray id derived from the stable key.
  int get trayId => id.hashCode.abs() % 100000;

  AppNotification copyWith({bool? read}) => AppNotification(
    animeId: animeId,
    animeTitle: animeTitle,
    episodeId: episodeId,
    episodeNumber: episodeNumber,
    createdAt: createdAt,
    posterUrl: posterUrl,
    read: read ?? this.read,
  );

  Map<String, dynamic> toJson() => <String, dynamic>{
    'animeId': animeId,
    'animeTitle': animeTitle,
    'episodeId': episodeId,
    'episodeNumber': episodeNumber,
    'posterUrl': posterUrl,
    'createdAt': createdAt.toIso8601String(),
    'read': read,
  };

  factory AppNotification.fromJson(Map<String, dynamic> json) =>
      AppNotification(
        animeId: json['animeId'] as String? ?? '',
        animeTitle: json['animeTitle'] as String? ?? '',
        episodeId: json['episodeId'] as String? ?? '',
        episodeNumber: (json['episodeNumber'] as num?)?.toInt() ?? 0,
        posterUrl: json['posterUrl'] as String?,
        createdAt:
            DateTime.tryParse(json['createdAt'] as String? ?? '') ??
            DateTime.fromMillisecondsSinceEpoch(0),
        read: json['read'] as bool? ?? false,
      );

  @override
  bool operator ==(Object other) => other is AppNotification && other.id == id;

  @override
  int get hashCode => Object.hash(animeId, episodeId, read);

  /// Keeps the sorting helper explicit for callers.
  static int newestFirst(AppNotification a, AppNotification b) =>
      b.createdAt.compareTo(a.createdAt);

  static int clampUnread(Iterable<AppNotification> items) =>
      min(99, items.where((item) => !item.read).length);
}
